def write_questions(dataset: Path):
    for name, rows in [("questions_pilot.jsonl",PILOT),("questions_final.jsonl",FINAL)]:
        (dataset/name).write_text("".join(json.dumps(x,ensure_ascii=False)+"\n" for x in rows),encoding="utf-8")
